import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing, random } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type RadialDataVizProps = Record<string, any>;

const RadialDataViz: React.FC<RadialDataVizProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  primaryColor = "#00936b",
  secondaryColor = "#222222",
  wireframeColor = "rgba(255, 255, 255, 0.3)",
  durationInSeconds = 10,
  barCount = 100,
  radiusPercent = 0.25,
  barMaxLength = 120,
  pulseSpeed = 1.5,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Safely handle background transparency
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Calculate Base Dimensions
  const minDim = Math.min(width, height);
  const radius = minDim * radiusPercent;
  const centerX = width / 2;
  const centerY = height / 2;

  // Animation: Intro Entrance (Spring)
  const entrance = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 100, mass: 0.8 },
  });

  // Animation: Continuous Pulse
  const pulse = Math.sin(frame * 0.05 * pulseSpeed) * 0.1 + 1; // 0.9 to 1.1 scale

  // Generate Bars
  const bars = useMemo(() => {
    return new Array(barCount).fill(0).map((_, i) => {
      const angle = (i / barCount) * 360;
      const isIlluminated = i < barCount * 0.75; // 75% illuminated
      return { index: i, angle, isIlluminated };
    });
  }, [barCount]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* CONTAINER FOR RADIAL ELEMENTS */}
        <div
          style={{
            position: "relative",
            width: radius * 2,
            height: radius * 2,
            transform: `scale(${entrance})`,
          }}
        >
          {/* CENTER ETHEREAL SPHERE */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              width: radius * 0.8,
              height: radius * 0.8,
              transform: "translate(-50%, -50%)",
              borderRadius: "50%",
              background: `radial-gradient(circle at 30% 30%, ${primaryColor}44, transparent 70%)`,
              boxShadow: `0 0 ${radius * 0.5}px ${primaryColor}22`,
              zIndex: 1,
            }}
          >
             {/* DATA STREAM TEXTURES (ROTATING RINGS) */}
             {[0.6, 0.8, 1.0].map((scale, idx) => {
               const rotate = interpolate(frame, [0, 360], [0, (idx % 2 === 0 ? 1 : -1) * 360 * 0.2]);
               return (
                 <div
                    key={idx}
                    style={{
                      position: "absolute",
                      top: 0, left: 0, right: 0, bottom: 0,
                      border: `1px dashed ${primaryColor}44`,
                      borderRadius: "50%",
                      transform: `scale(${scale}) rotate(${rotate}deg)`,
                      opacity: 0.6,
                    }}
                 />
               )
             })}
          </div>
          
          {/* BARS */}
          {bars.map((bar) => {
            // Pseudo Audio-Reaction Logic
            // Create a complex wave pattern using sin/cos and index
            const wave = Math.sin((frame * 0.1 * pulseSpeed) + (bar.index * 0.2)) 
                       * Math.cos((frame * 0.05) - (bar.index * 0.1));
            
            // Map wave (-1 to 1) to a height multiplier (0.2 to 1.0)
            const heightMultiplier = interpolate(wave, [-1, 1], [0.2, 1], {
               extrapolateLeft: "clamp", extrapolateRight: "clamp"
            });

            const currentHeight = barMaxLength * heightMultiplier;

            // Opacity fade in for bars slightly staggered
            const barOpacity = interpolate(
                frame, 
                [bar.index * 0.5, bar.index * 0.5 + 20], 
                [0, 1], 
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            // Styling based on 75/25 split
            const barStyle: React.CSSProperties = bar.isIlluminated
              ? {
                  backgroundColor: primaryColor,
                  boxShadow: `0 0 10px ${primaryColor}`,
                  opacity: barOpacity,
                }
              : {
                  backgroundColor: secondaryColor,
                  border: `1px solid ${wireframeColor}`,
                  opacity: barOpacity * 0.6, // Faint
                };

            return (
              <div
                key={bar.index}
                style={{
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: 4, // Thin bars
                  height: currentHeight,
                  transformOrigin: "center bottom", // Rotate around the inner circle
                  // Complex transform: Rotate to angle -> Move out to radius -> Rotate 180 to point outwards (if needed)
                  // Actually easier: Rotate to angle, Translate Y by radius (push out), Scale Y for audio effect
                  transform: `
                    rotate(${bar.angle}deg) 
                    translateY(-${radius}px) 
                    translateY(-50%)
                  `,
                  borderRadius: 2,
                  ...barStyle,
                }}
              />
            );
          })}
        </div>

        {/* LEFT STAT: 25% (Moved to Upper-Left) */}
        <div
          style={{
            position: "absolute",
            left: "10%",
            top: "15%",
            transform: `scale(${entrance})`,
            fontSize: minDim * 0.12,
            fontWeight: 700,
            color: "rgba(255, 255, 255, 0.4)",
            opacity: entrance,
            zIndex: 10,
          }}
        >
          25%
        </div>

        {/* RIGHT STAT: 70% (Moved to Lower-Right) */}
        <div
          style={{
            position: "absolute",
            right: "10%",
            bottom: "15%",
            transform: `scale(${entrance})`,
            fontSize: minDim * 0.12,
            fontWeight: 700,
            color: primaryColor,
            opacity: entrance,
            zIndex: 10,
          }}
        >
          70%
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default RadialDataViz;